var l=[{title:`Lehetséges helyettesítők`,text:`Egy zárt hátizsák egyenletesen elosztott tartalommal ellenállást adhat egy guggoláshoz vagy hordozáshoz. A vizes palackok könnyű kézi súlyként működnek, egy erős lépcső pedig helyettesítheti az alacsony gyakorlati emelvényt. Ezeken a tárgyakon nincs szabványos méret vagy súlyjelölés, ezért a terhelés és az egyensúly előzetes figyelmeztetés nélkül eltolódhat.`},{title:`A bútor komoly kockázat`,text:`Egy étkezőszék elcsúszhat vagy felborulhat tolódzkodás, lépcsőre lépés vagy döntött fekvőtámasz közben, és sok asztal nem bírja el a testsúlyos evezést, amelyet az él alól húzol. Soha ne feltételezd, hogy egy közönséges asztal, törölköző, ajtókilincs vagy polc elbírja a testsúlyodat. Ha egy felállás olyan erőre vagy rögzítésre épül, amiben nem vagy biztos, válassz másik gyakorlatot.`},{title:`Ellenőrizz minden tárgyat`,text:`Győződj meg róla, hogy a felület nem csúszik, a tartály nem szivárog és nincs törött füle, és a hátizsák pántjai nem szakadnak. Oszd el úgy a súlyt, hogy ne lengjen hirtelen. Kerüld az üvegedényeket, az éles fémszéleket és a laza könyvkötegeket. Tiszta padlón edzz, minden törékeny dologtól távol.`},{title:`Haladj lassan`,text:`Kezdj egyszerű mozdulattal és kis terheléssel. A lassú, megismételhető ismétlések jobbak a trükkös egyensúlyozásnál. Ha nem tudod megbízhatóan lemérni a tárgyat, pontos szám helyett jegyezd fel a felállást és az ellenállás durva becslését. Minden emelés legyen elég kicsi ahhoz, hogy kontroll alatt maradj.`},{title:`A TrainUp használata`,text:`Egy háztartási tárgy nem pad, állvány, húzódzkodórúd vagy csigás állomás. A Profilban csak a valódi felszerelésre add meg a pad típusát vagy a húzódzkodórudat. Ha nem lehetsz biztos benne, hogy egy bútor biztonságos, válassz olyan saját testsúlyos gyakorlatokat, amelyekhez nincs szükség támaszra.`}];var s=[{label:`Mayo Clinic: súlyzós edzés biztonsága és technikája`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`ACE gyakorlatkönyvtár`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:l,sources:s};export{a as default,l as sections,s as sources};